CREATE TABLE [dbo].[ccRIALog](	  [log_id] INT NOT NULL IDENTITY(1,1)	, [areaName] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [operationDate] DATETIME NOT NULL	, [operationType] TINYINT NOT NULL	, [login] VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [module_id] TINYINT NOT NULL	, [value] VARCHAR(250) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [target] VARCHAR(250) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, CONSTRAINT [PK_ccRIALog] PRIMARY KEY ([log_id] ASC))